BEGIN;
create function pg_temp.ok(b boolean,label text) returns void language plpgsql as $$begin if b is distinct from true then raise exception '%',label;end if;end$$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when raise_exception or insufficient_privilege or check_violation then return;end;raise exception 'Expected denial: %',label;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,aud,role) select ('de000000-0000-4000-8000-00000000000'||n)::uuid,'evidence-'||n||'@example.invalid',now(),'{"pms_admin_provisioned":true}','authenticated','authenticated' from generate_series(1,3)n;
insert into workspaces(id,name) values('de000000-0000-4000-8000-000000000010','Evidence fixture');
insert into workspace_members(workspace_id,user_id,role,display_name) select 'de000000-0000-4000-8000-000000000010',('de000000-0000-4000-8000-00000000000'||n)::uuid,case n when 1 then 'owner' when 2 then 'member' else 'client' end,'Person '||n from generate_series(1,3)n;
select set_config('request.jwt.claims','{"sub":"de000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into projects(id,workspace_id,name,client_name,client_tools) values('de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000010','Evidence project','Client',array['tasks','files']),('de000000-0000-4000-8000-000000000021','de000000-0000-4000-8000-000000000010','Other project','Other',array['tasks']);
insert into project_members values('de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000003','guest');
insert into tasks(id,workspace_id,project_id,title,is_published) values('de000000-0000-4000-8000-000000000030','de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','Shared task',true),('de000000-0000-4000-8000-000000000031','de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','Internal secret',false);
insert into project_files(id,workspace_id,project_id,name,path) values('de000000-0000-4000-8000-000000000040','de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','Receipt.pdf','de000000-0000-4000-8000-000000000010/de000000-0000-4000-8000-000000000020/receipt.pdf');
insert into project_expenses(id,workspace_id,project_id,description,amount,expense_date,reimbursable,task_id,receipt_file_id) values('de000000-0000-4000-8000-000000000050','de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','Licence',20,current_date,true,'de000000-0000-4000-8000-000000000030','de000000-0000-4000-8000-000000000040');
select pg_temp.denied($q$update project_expenses set project_id='de000000-0000-4000-8000-000000000021' where id='de000000-0000-4000-8000-000000000050'$q$,'cross-project evidence');
select create_work_invoice('de000000-0000-4000-8000-000000000020','{}',array['de000000-0000-4000-8000-000000000050'::uuid],current_date+14,gen_random_uuid(),true);
select pg_temp.ok((select snapshot->'receipt_evidence'->>'name'='Receipt.pdf' and snapshot->'task_evidence'->>'title'='Shared task' from invoice_sources where expense_id='de000000-0000-4000-8000-000000000050'),'invoice snapshots evidence');
select pg_temp.ok((select not is_published from project_files where id='de000000-0000-4000-8000-000000000040'),'receipt remains private');
select pg_temp.ok(is_reviewed_file('de000000-0000-4000-8000-000000000010/de000000-0000-4000-8000-000000000020/receipt.pdf'),'storage object protection includes invoice receipt');
select pg_temp.denied($q$select prepare_project_file_delete('de000000-0000-4000-8000-000000000010/de000000-0000-4000-8000-000000000020/receipt.pdf')$q$,'API deletion reservation denied');
select pg_temp.denied($q$delete from project_files where id='de000000-0000-4000-8000-000000000040'$q$,'direct file deletion denied');
update invoices set status='Cancelled' where workspace_id='de000000-0000-4000-8000-000000000010';
update project_expenses set receipt_file_id=null,description='Corrected licence' where id='de000000-0000-4000-8000-000000000050';
select pg_temp.denied($q$update project_files set path='changed' where id='de000000-0000-4000-8000-000000000040'$q$,'released snapshot still retains original content');
insert into time_entries(workspace_id,project_id,task_id,description,minutes,status,billing_treatment,cost_rate,bill_rate) values
('de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000030','Private note',60,'Approved','covered',90,180),
('de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000031','Internal note',120,'Approved','covered',90,180),
('de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000030','Not approved',30,'Submitted','covered',90,180);
insert into retainers(workspace_id,project_id,period,hours,rollover) values('de000000-0000-4000-8000-000000000010','de000000-0000-4000-8000-000000000020',date_trunc('month',current_date)::date,10,2);
select pg_temp.denied($q$select client_time_report('de000000-0000-4000-8000-000000000020',current_date,current_date,'de000000-0000-4000-8000-000000000003')$q$,'disabled by default');
update projects set client_time_report_enabled=true,client_retainer_report_enabled=true where id='de000000-0000-4000-8000-000000000020';
select pg_temp.ok((select jsonb_array_length(r->'entries')=1 and r->'retainers'->0->>'shared_covered_minutes'='60' and r::text not like '%Private note%' and r::text not like '%cost_rate%' and r::text not like '%Internal secret%' and r::text not like '%bill_rate%' from(select client_time_report('de000000-0000-4000-8000-000000000020',current_date,current_date,'de000000-0000-4000-8000-000000000003') r)s),'preview excludes private data and uses shared-only usage');
select set_config('request.jwt.claims','{"sub":"de000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select pg_temp.ok(jsonb_array_length(client_time_report('de000000-0000-4000-8000-000000000020',current_date,current_date)->'entries')=1,'invited client report');
select pg_temp.ok((select count(*)=0 from time_entries where workspace_id='de000000-0000-4000-8000-000000000010'),'no raw time access');
select pg_temp.denied($q$select client_time_report('de000000-0000-4000-8000-000000000021',current_date,current_date)$q$,'other project denied');
select pg_temp.denied($q$select client_time_report('de000000-0000-4000-8000-000000000020',current_date,current_date,'de000000-0000-4000-8000-000000000001')$q$,'client cannot impersonate');
reset role;
select set_config('request.jwt.claims','{"sub":"de000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
update tasks set is_published=false where id='de000000-0000-4000-8000-000000000030';
select pg_temp.ok(jsonb_array_length(client_time_report('de000000-0000-4000-8000-000000000020',current_date,current_date,'de000000-0000-4000-8000-000000000003')->'entries')=0,'unsharing task removes time');

update tasks set is_published=true where id='de000000-0000-4000-8000-000000000030';
update projects set client_tools=array['tasks','files','discussions'] where id='de000000-0000-4000-8000-000000000020';
create temp table fixture_register_ids(k text,id uuid);
grant all on fixture_register_ids to authenticated;
set local role authenticated;
insert into fixture_register_ids select 'original',save_project_register('de000000-0000-4000-8000-000000000020',null,0,'Decision','Choose first layout','{"maker":"Project lead","rationale":"Tested navigation"}','Decided',current_date,'Task','de000000-0000-4000-8000-000000000030',false);
select pg_temp.ok(jsonb_array_length(preview_project_registers('de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000003'))=0,'internal decision absent from preview');
select save_project_register('de000000-0000-4000-8000-000000000020',(select id from fixture_register_ids where k='original'),1,'Decision','Choose first layout','{"maker":"Project lead","rationale":"Tested navigation"}','Decided',current_date,'Task','de000000-0000-4000-8000-000000000030',true);
select pg_temp.ok(jsonb_array_length(preview_project_registers('de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000003'))=1,'shared decision in preview');
select pg_temp.denied($q$select save_project_register('de000000-0000-4000-8000-000000000020',(select id from fixture_register_ids where k='original'),1,'Decision','Stale edit','{"maker":"Lead","rationale":"Old"}','Decided',current_date,null,null,true)$q$,'stale revision rejected');
insert into fixture_register_ids select 'replacement',save_project_register('de000000-0000-4000-8000-000000000020',null,0,'Decision','Choose tested layout','{"maker":"Project lead","rationale":"New usability evidence"}','Decided',current_date,null,null,true);
select save_project_register('de000000-0000-4000-8000-000000000020',(select id from fixture_register_ids where k='original'),2,'Decision','Choose first layout','{"maker":"Project lead","rationale":"Original rationale retained"}','Superseded',current_date,'Task','de000000-0000-4000-8000-000000000030',true,(select id from fixture_register_ids where k='replacement'));
select pg_temp.ok((select count(*)=3 from project_register_history where record_id=(select id from fixture_register_ids where k='original')),'append revision history');
select pg_temp.denied($q$select save_project_register('de000000-0000-4000-8000-000000000020',(select id from fixture_register_ids where k='replacement'),1,'Decision','Cycle','{"maker":"Lead","rationale":"Cycle"}','Superseded',current_date,null,null,true,(select id from fixture_register_ids where k='original'))$q$,'supersession cycle rejected');
select pg_temp.denied($q$select save_project_register('de000000-0000-4000-8000-000000000021',null,0,'Finding','Wrong project','{"evidence_type":"Observation","severity":"High","flow":"Checkout","evidence":"Measured contrast","recommendation":"Increase contrast"}','Open',current_date,'Task','de000000-0000-4000-8000-000000000030',false)$q$,'cross-project source rejected');
select pg_temp.denied($q$select save_project_register('de000000-0000-4000-8000-000000000020',null,0,'Finding','Missing validation','{"evidence_type":"Hypothesis","severity":"High","flow":"Checkout","evidence":"Possible confusion","recommendation":"Test flow"}','Validated',current_date,null,null,false)$q$,'validation result required');
insert into fixture_register_ids select 'finding',save_project_register('de000000-0000-4000-8000-000000000020',null,0,'Finding','Contrast finding','{"evidence_type":"Observation","severity":"High","flow":"Checkout","criterion":"WCAG 1.4.3","evidence":"Measured ratio","recommendation":"Increase contrast","owner":"Design lead"}','Open',current_date,null,null,false);
select set_config('request.jwt.claims','{"sub":"de000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select pg_temp.ok((select count(*)=2 from project_registers where project_id='de000000-0000-4000-8000-000000000020'),'actual client sees shared decisions only');
select pg_temp.ok((select count(*)=0 from project_register_history),'history stays internal');
select pg_temp.denied($q$update project_registers set title='Rewrite'$q$,'direct writes prohibited');
select pg_temp.denied($q$select save_project_register('de000000-0000-4000-8000-000000000020',null,0,'Decision','Client write','{"maker":"Client","rationale":"Not allowed"}','Decided',current_date,null,null,true)$q$,'client cannot author team register');
reset role;
select set_config('request.jwt.claims','{"sub":"de000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
update tasks set is_published=false where id='de000000-0000-4000-8000-000000000030';
set local role authenticated;
select pg_temp.ok(jsonb_array_length(preview_project_registers('de000000-0000-4000-8000-000000000020','de000000-0000-4000-8000-000000000003'))=1,'unsharing source hides linked decision');
select delete_workspace('de000000-0000-4000-8000-000000000010','Evidence fixture');
ROLLBACK;
